const item = $input.first();
const triggerData = $('Google Drive Trigger').item.json;
const config = $('Set: Research Config').item.json;

if (config.anthropic_api_key.startsWith('YOUR_')) {
  throw new Error('Set your Anthropic API key in Set: Research Config node.');
}

const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = binaryData.toString('base64');

if (!base64String || base64String.length < 100) {
  throw new Error('PDF binary data is empty or unreadable.');
}

return [{
  json: {
    claude_request: {
      model: config.model,
      max_tokens: 8096,
      temperature: 0,
      messages: [{
        role: 'user',
        content: [
          { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64String } },
          { type: 'text', text: 'Extract all text from this PDF. Return only raw text preserving paragraph breaks. No commentary, no analysis.' }
        ]
      }]
    },
    filename: triggerData.name,
    anthropic_api_key: config.anthropic_api_key,
    research_question: config.research_question,
    analysis_method: config.analysis_method,
    domain: config.domain,
    chunk_size_words: config.chunk_size_words,
    enable_ai_coding: config.enable_ai_coding,
    model: config.model
  }
}];

const apiResponse = $input.first().json;
const prepNode = $('Code: Prepare PDF Extraction').item.json;

if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
  throw new Error('PDF extraction failed: ' + JSON.stringify(apiResponse).substring(0, 200));
}

const extractedText = apiResponse.content[0].text.trim();

if (extractedText.length < 50) {
  throw new Error('Very little text extracted. PDF may be image-based. Convert to text-based PDF.');
}

return [{
  json: {
    extracted_text: extractedText,
    filename: prepNode.filename,
    extraction_method: 'claude_pdf',
    char_count: extractedText.length,
    research_question: prepNode.research_question,
    analysis_method: prepNode.analysis_method,
    domain: prepNode.domain,
    chunk_size_words: prepNode.chunk_size_words,
    enable_ai_coding: prepNode.enable_ai_coding,
    model: prepNode.model,
    anthropic_api_key: prepNode.anthropic_api_key
  }
}];

const item = $input.first().json;
const triggerData = $('Google Drive Trigger').item.json;
const config = $('Set: Research Config').item.json;

const rawText = (item.text || item.data || '').trim();

if (!rawText || rawText.length < 50) {
  throw new Error('Insufficient text from Word document. Convert to PDF for best results.');
}

return [{
  json: {
    extracted_text: rawText,
    filename: triggerData.name,
    extraction_method: 'n8n_extract',
    char_count: rawText.length,
    research_question: config.research_question,
    analysis_method: config.analysis_method,
    domain: config.domain,
    chunk_size_words: config.chunk_size_words,
    enable_ai_coding: config.enable_ai_coding,
    model: config.model,
    anthropic_api_key: config.anthropic_api_key
  }
}];

const data = $input.first().json;

if (!data.extracted_text || data.extracted_text.trim().length === 0) {
  throw new Error('No text available for analysis.');
}

const text = data.extracted_text
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]{2,}/g, ' ')
  .trim();

const chunkSizeWords = parseInt(data.chunk_size_words) || 300;
const overlap = 40;
const words = text.split(/\s+/).filter(w => w.length > 0);
const chunks = [];

for (let i = 0; i < words.length; i += (chunkSizeWords - overlap)) {
  const end = Math.min(i + chunkSizeWords, words.length);
  chunks.push(words.slice(i, end).join(' '));
  if (end >= words.length) break;
}

return chunks.map((chunk, idx) => ({
  json: {
    chunk_text: chunk,
    chunk_index: idx,
    total_chunks: chunks.length,
    word_count: chunk.split(/\s+/).length,
    source_name: data.filename,
    research_question: data.research_question,
    analysis_method: data.analysis_method,
    domain: data.domain,
    model: data.model,
    anthropic_api_key: data.anthropic_api_key,
    enable_ai_coding: data.enable_ai_coding,
    started_at: new Date().toISOString()
  }
}));

const apiResponse = $input.first().json;
const meta = $('Code: Build Step1 Request').item.json;

if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
  return [{
    json: {
      codes: [],
      chunk_index: meta.chunk_index,
      total_chunks: meta.total_chunks,
      source_name: meta.source_name,
      research_question: meta.research_question,
      analysis_method: meta.analysis_method,
      domain: meta.domain,
      model: meta.model,
      anthropic_api_key: meta.anthropic_api_key,
      enable_ai_coding: meta.enable_ai_coding,
      started_at: meta.started_at,
      parse_error: 'No content in API response: ' + JSON.stringify(apiResponse).substring(0, 200)
    }
  }];
}

let rawText = apiResponse.content[0].text.trim();

// Strip markdown code fences if present
rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  // Attempt to extract JSON object from surrounding text
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      return [{
        json: {
          codes: [],
          chunk_index: meta.chunk_index,
          total_chunks: meta.total_chunks,
          source_name: meta.source_name,
          research_question: meta.research_question,
          analysis_method: meta.analysis_method,
          domain: meta.domain,
          model: meta.model,
          anthropic_api_key: meta.anthropic_api_key,
          enable_ai_coding: meta.enable_ai_coding,
          started_at: meta.started_at,
          parse_error: 'JSON parse failed: ' + e2.message
        }
      }];
    }
  } else {
    return [{
      json: {
        codes: [],
        chunk_index: meta.chunk_index,
        total_chunks: meta.total_chunks,
        source_name: meta.source_name,
        research_question: meta.research_question,
        analysis_method: meta.analysis_method,
        domain: meta.domain,
        model: meta.model,
        anthropic_api_key: meta.anthropic_api_key,
        enable_ai_coding: meta.enable_ai_coding,
        started_at: meta.started_at,
        parse_error: 'No JSON found in response: ' + e.message
      }
    }];
  }
}

const rawCodes = (parsed.codes || []);
const validCodes = rawCodes.filter(c => c && c.code && c.quotation);

return [{
  json: {
    codes: validCodes,
    chunk_index: meta.chunk_index,
    total_chunks: meta.total_chunks,
    source_name: meta.source_name,
    research_question: meta.research_question,
    analysis_method: meta.analysis_method,
    domain: meta.domain,
    model: meta.model,
    anthropic_api_key: meta.anthropic_api_key,
    enable_ai_coding: meta.enable_ai_coding,
    started_at: meta.started_at,
    tokens_used: (apiResponse.usage || {}).input_tokens || 0 + (apiResponse.usage || {}).output_tokens || 0
  }
}];

const allItems = $input.all();

if (!allItems || allItems.length === 0) {
  throw new Error('No chunk results to aggregate.');
}

const meta = allItems[0].json;
let allCodes = [];
let totalTokens = 0;
const errors = [];

for (const item of allItems) {
  const d = item.json;
  if (d.parse_error) {
    errors.push('Chunk ' + d.chunk_index + ': ' + d.parse_error);
  }
  if (Array.isArray(d.codes)) {
    allCodes = allCodes.concat(d.codes);
  }
  totalTokens += (d.tokens_used || 0);
}

return [{
  json: {
    all_codes: allCodes,
    total_codes: allCodes.length,
    total_chunks_processed: allItems.length,
    total_tokens_step1: totalTokens,
    source_name: meta.source_name,
    research_question: meta.research_question,
    analysis_method: meta.analysis_method,
    domain: meta.domain,
    model: meta.model,
    anthropic_api_key: meta.anthropic_api_key,
    enable_ai_coding: meta.enable_ai_coding,
    started_at: meta.started_at,
    step1_completed_at: new Date().toISOString(),
    step1_errors: errors
  }
}];

const apiResponse = $input.first().json;
const meta = $('Code: Build Step2 Request').item.json;

if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
  throw new Error('Step 2 clustering failed: ' + JSON.stringify(apiResponse).substring(0, 200));
}

let rawText = apiResponse.content[0].text.trim();
rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  const match = rawText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      throw new Error('Step 2 JSON parse failed: ' + e2.message + ' | Raw: ' + rawText.substring(0, 300));
    }
  } else {
    throw new Error('Step 2 no JSON found: ' + e.message);
  }
}

const clusters = parsed.clusters || [];
const overallFinding = parsed.overall_finding || '';
const analyticalMemo = parsed.analytical_memo || '';
const tokensUsed = ((apiResponse.usage || {}).input_tokens || 0) + ((apiResponse.usage || {}).output_tokens || 0);

return [{
  json: {
    clusters: clusters,
    total_themes: clusters.length,
    overall_finding: overallFinding,
    analytical_memo: analyticalMemo,
    all_codes: meta.all_codes,
    total_codes: meta.total_codes,
    source_name: meta.source_name,
    research_question: meta.research_question,
    analysis_method: meta.analysis_method,
    domain: meta.domain,
    model: meta.model,
    anthropic_api_key: meta.anthropic_api_key,
    enable_ai_coding: meta.enable_ai_coding,
    started_at: meta.started_at,
    step1_completed_at: meta.step1_completed_at,
    step2_completed_at: new Date().toISOString(),
    total_tokens_step1: meta.total_tokens_step1,
    total_tokens_step2: tokensUsed,
    step1_errors: meta.step1_errors
  }
}];

const apiResponse = $input.first().json;
const meta = $('Code: Build Step3 Request').item.json;

let aiCodes = [];
let aiDiscourseSummary = '';
let step3TokensUsed = 0;
const errors = Array.isArray(meta.step1_errors) ? [...meta.step1_errors] : [];

if (meta.ai_coding_skipped) {
  aiDiscourseSummary = 'AI discourse coding was disabled (enable_ai_coding = false).';
} else if (!apiResponse.content || !apiResponse.content[0] || !apiResponse.content[0].text) {
  errors.push('Step 3 AI coding failed: No content in API response.');
} else {
  let rawText = apiResponse.content[0].text.trim();
  rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    const match = rawText.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        parsed = JSON.parse(match[0]);
      } catch (e2) {
        errors.push('Step 3 JSON parse failed: ' + e2.message);
        parsed = null;
      }
    } else {
      errors.push('Step 3 no JSON found: ' + e.message);
      parsed = null;
    }
  }

  if (parsed) {
    aiCodes = parsed.ai_specific_codes || [];
    aiDiscourseSummary = parsed.ai_discourse_summary || '';
    step3TokensUsed = ((apiResponse.usage || {}).input_tokens || 0) + ((apiResponse.usage || {}).output_tokens || 0);
  }
}

const totalTokens = (meta.total_tokens_step1 || 0) + (meta.total_tokens_step2 || 0) + step3TokensUsed;

const finalOutput = {
  metadata: {
    source_name: meta.source_name,
    research_question: meta.research_question,
    domain: meta.domain,
    analysis_method: meta.analysis_method,
    model_used: meta.model,
    step1_completed_at: meta.step1_completed_at,
    step2_completed_at: meta.step2_completed_at,
    step3_completed_at: new Date().toISOString(),
    total_codes: meta.total_codes,
    total_themes: meta.total_themes,
    total_ai_codes: aiCodes.length,
    total_tokens_used: totalTokens
  },
  overall_finding: meta.overall_finding,
  analytical_memo: meta.analytical_memo,
  step2_clusters: meta.clusters,
  step1_codes: meta.all_codes,
  step3_ai_codes: aiCodes,
  ai_discourse_summary: aiDiscourseSummary,
  errors: errors
};

return [{ json: finalOutput }];
